// --- Model Intercept ---
const float model_intercept = 1814.005096;

const float offset_values[] = {542, 530, 528, 532, 544, 544, 537, 527, 528, 530};

const uint16_t NUM_POLY_FEATURES = sizeof(model_coefs)/sizeof(model_coefs[0]);

int32_t XYStagePositionModel::predictFromRaw(const int raw[]) {
    if(!raw) return INT32_MIN;
    for(uint8_t i=0;i<NUM_FEATURES;++i) if(!SensorFaultPolicy::adcValid(raw[i])) return INT32_MIN;
    // Use double for numerical parity with Python's float64
    double x_scaled[NUM_FEATURES];
    double x_poly[NUM_POLY_FEATURES];

    int index = 0;

    // --- Step 1: Standardize features (subtract mean & divide by scale). Offsets kept 0. ---
    for (int i = 0; i < NUM_FEATURES; i++) {
        double mean  = pgm_read_float_near(scaler_mean  + i);
        double scale = pgm_read_float_near(scaler_scale + i);
        x_scaled[i]  = (-((double)raw[i] - offset_values[i]) - mean) / scale;
    }

    // --- Step 2: Generate polynomial features up to degree 5 (with replacement combos) ---
    // degree = 1
    for (int i = 0; i < NUM_FEATURES; ++i) {
        x_poly[index++] = x_scaled[i];
    }

    // degree = 2
    for (int i = 0; i < NUM_FEATURES; ++i) {
        for (int j = i; j < NUM_FEATURES; ++j) {
            x_poly[index++] = x_scaled[i] * x_scaled[j];
        }
    }

    // degree = 3
    for (int i = 0; i < NUM_FEATURES; ++i) {
        for (int j = i; j < NUM_FEATURES; ++j) {
            for (int k = j; k < NUM_FEATURES; ++k) {
                x_poly[index++] = x_scaled[i] * x_scaled[j] * x_scaled[k];
            }
        }
    }

    // degree = 4
    for (int i = 0; i < NUM_FEATURES; ++i) {
        for (int j = i; j < NUM_FEATURES; ++j) {
            for (int k = j; k < NUM_FEATURES; ++k) {
                for (int l = k; l < NUM_FEATURES; ++l) {
                    x_poly[index++] = x_scaled[i] * x_scaled[j] * x_scaled[k] * x_scaled[l];
                }
            }
        }
    }

    // degree = 5
    for (int i = 0; i < NUM_FEATURES; ++i) {
        for (int j = i; j < NUM_FEATURES; ++j) {
            for (int k = j; k < NUM_FEATURES; ++k) {
                for (int l = k; l < NUM_FEATURES; ++l) {
                    for (int m = l; m < NUM_FEATURES; ++m) {
                        x_poly[index++] = x_scaled[i] * x_scaled[j] * x_scaled[k] * x_scaled[l] * x_scaled[m];
                    }
                }
            }
        }
    }

    double prediction = (double)model_intercept;
    for (int i = 0; i < NUM_POLY_FEATURES; ++i) {
        double coef = pgm_read_float_near(model_coefs + i);
        prediction += coef * x_poly[i];
    }

    // --- Step 4: Round to int (same as Python's round) ---
    if(!isfinite(prediction) || prediction <= (double)INT32_MIN+1 || prediction >= (double)INT32_MAX) return INT32_MIN;
    return (int32_t)llround(prediction);
}

